<?php
namespace EIPSI\AssessmentEditor\Runtime;
use EIPSI\AssessmentEditor\Definition as D;
/** Strict shared NATIVE_PROCESS_V1 ingestion. Intermediary text content never crosses this owner. */
final class Metadata {
    private static function keys(array $v,array $allowed): void {foreach($v as $k=>$x)if(!in_array($k,$allowed,true))D::fail('Unknown metadata field');}
    private static function number($v): void {if(!is_int($v)&&!is_float($v))D::fail('Invalid metadata number');if(!is_finite((float)$v)||$v<0||$v>1e15)D::fail('Invalid metadata number');}
    private static function state($v,array $e): void {
        if(in_array($e['type'],array('text','textarea','email','tel','url'),true)){if(!is_array($v)||array_keys($v)!==array('length')||!is_int($v['length'])||$v['length']<0||$v['length']>100000)D::fail('Text metadata must contain length only');return;}
        if($v===null)return;
        if(in_array($e['type'],array('single_choice','select','likert','matrix'),true)){if(!is_string($v)||!in_array($v,array_column($e['options'],'id'),true))D::fail('Invalid metadata choice');return;}
        if($e['type']==='multiple_choice'){if(!is_array($v)||count($v)>100||($v&&array_keys($v)!==range(0,count($v)-1)))D::fail('Invalid metadata choices');foreach($v as $id)if(!is_string($id)||!in_array($id,array_column($e['options'],'id'),true))D::fail('Invalid metadata choice');return;}
        if($e['type']==='date'){if($v==='')return;if(!is_string($v)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v))D::fail('Invalid metadata date');return;}
        if((!is_int($v)&&!is_float($v))||!is_finite((float)$v))D::fail('Invalid metadata numeric state');
    }
    public static function validate(array $m,array $d,string $version): array {
        if(strlen(D::json($m))>524288)D::fail('Metadata volume exceeded');
        self::keys($m,array('contract','assessment_id','definition_ref','started_at','completed_at','duration','status','recovery_used','recovery_count','pages','items','events','dropped_events','context'));
        if(($m['contract']??'')!=='NATIVE_PROCESS_V1'||($m['assessment_id']??'')!==$d['id']||!in_array($m['status']??'',array('active','suspended','completed'),true))D::fail('Invalid metadata contract');
        foreach(array('started_at','duration','recovery_count','dropped_events') as $key)self::number($m[$key]??null);if(($m['completed_at']??null)!==null)self::number($m['completed_at']);if(!is_bool($m['recovery_used']??null))D::fail('Invalid recovery metadata');
        $items=array();$ids=array();$visit=function($elements)use(&$visit,&$items,&$ids){foreach($elements as $e){if($e['type']==='matrix')foreach($e['properties']['matrix_rows'] as $i=>$r){$item=$e;$item['id']=$r['id'];$item['response_key']=$r['response_key'];$item['properties']['variable_name']=$e['properties']['variable_name'].'_'.($i+1);$items[$r['response_key']]=$item;$ids[$r['id']]=$item;}elseif($e['response_key']){$items[$e['response_key']]=$e;$ids[$e['id']]=$e;}$visit($e['children']);}};$visit($d['elements']);
        foreach(array('pages','items','events') as $key)if(!isset($m[$key])||!is_array($m[$key]))D::fail('Invalid metadata collection');
        $pages=array_column($d['flow']['pages'],'id');if(count($m['pages'])>count($pages)||count($m['items'])>count($items)||count($m['events'])>2048)D::fail('Metadata bounds exceeded');
        foreach($m['pages'] as $id=>$p){if(!in_array($id,$pages,true)||!is_array($p)||($p['page_id']??null)!==$id)D::fail('Invalid metadata page');self::keys($p,array('page_id','presented_at','leave_at','duration','visit_count','revisit_count','next_transitions','previous_transitions','resumed_here','current_presented_at'));foreach($p as $k=>$v)if($k==='resumed_here'){if(!is_bool($v))D::fail('Invalid page flag');}elseif($k!=='page_id'&&$v!==null)self::number($v);}
        foreach($m['items'] as $key=>&$v){if(!isset($items[$key])||!is_array($v))D::fail('Invalid metadata item');$e=$items[$key];self::keys($v,array('item_id','response_key','variable_name','presented_at','first_interaction_at','final_response_at','time_to_first_interaction','time_to_final_response','interaction_count','change_count','focus_count','focus_duration','initial_state','first_interacted_state','final_state','visit_count','revisit_count','trajectory','input_method'));if(($v['item_id']??'')!==$e['id']||($v['response_key']??'')!==$key)D::fail('Metadata identity mismatch');$v['variable_name']=$e['properties']['variable_name'];foreach($v as $k=>$value){if(in_array($k,array('item_id','response_key','variable_name','trajectory'),true))continue;if($k==='input_method'){if(!in_array($value,array('unknown','pointer','keyboard','touch'),true))D::fail('Invalid input method');}elseif(in_array($k,array('initial_state','first_interacted_state','final_state'),true)){if($value!==null)self::state($value,$e);}elseif($value!==null)self::number($value);}
            if(!isset($v['trajectory'])||!is_array($v['trajectory'])||count($v['trajectory'])>128)D::fail('Trajectory bounds');foreach($v['trajectory'] as $event){if(!is_array($event))D::fail('Invalid trajectory');D::fields($event,array('timestamp','state'));self::number($event['timestamp']);self::state($event['state'],$e);}if($d['flow']['metadata_profile']!=='detailed'&&$v['trajectory'])D::fail('Trajectory profile mismatch');
        }unset($v);
        foreach($m['events'] as $event){if(!is_array($event))D::fail('Invalid event');D::fields($event,array('timestamp','kind','identity','state'));self::number($event['timestamp']);if(!in_array($event['kind'],array('presented','revisit','next','previous','leave','suspend','focus','blur','first_interaction','clear','interaction','resume','final_response'),true))D::fail('Invalid event kind');$identity=$event['identity'];if($identity!==null&&!isset($ids[$identity])&&!in_array($identity,$pages,true))D::fail('Event identity mismatch');if($event['state']!==null){if(!isset($ids[$identity])||$d['flow']['metadata_profile']!=='detailed')D::fail('Invalid event state');self::state($event['state'],$ids[$identity]);}}
        if($d['flow']['metadata_profile']==='basic'&&($m['events']||isset($m['context'])))D::fail('Basic profile mismatch');
        if(isset($m['context'])){if(!is_array($m['context']))D::fail('Invalid context');self::keys($m['context'],array('device','browser','os','screen','viewport','timezone','language','input_capabilities'));foreach($m['context'] as $k=>$v){if(in_array($k,array('screen','viewport'),true)){if(!is_array($v))D::fail('Invalid dimensions');D::fields($v,array('width','height'));foreach($v as $n)self::number($n);}elseif($k==='input_capabilities'){if(!is_array($v))D::fail('Invalid capabilities');D::fields($v,array('touch','pointer'));foreach($v as $b)if(!is_bool($b))D::fail('Invalid capabilities');}elseif(!is_string($v)||strlen($v)>256)D::fail('Invalid context string');}}
        $m['definition_ref']=array('kind'=>'NATIVE_PUBLISHED_SNAPSHOT','version_id'=>$version,'assessment_id'=>$d['id'],'sha256'=>hash('sha256',D::json($d)));return $m;
    }
}
